/*
 * A081220  Palindromic primes = 1 mod 4.
 * https://oeis.org/A081220
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 3, u16 n <= 33, u32 n <= 33, u64 n <= 1500,
 *            u128 n <= 1500, big any n
 * Helpers:   is_prime_big, pow_int_seq, reverse_digits
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A081220: palindromic primes ≡ 1 (mod 4) – generated by testing
 * palindromes of odd length.
 * The function builds the prime list incrementally; each call guarantees
 * that a(n) is available. */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>

/* helpers from the utils package */
#include "../utils/is_prime_big.h"   /* bool is_prime_big(seq_t n); */
#include "../utils/reverse_digits.h" /* seq_t reverse_digits(seq_t x); */
#include "../utils/pow_int_seq.h"   /* seq_t pow_int_seq(seq_t base, idx_t exp); */

/* dynamic array of found primes */
static seq_t *prime_list = NULL;
static size_t prime_count = 0;
static size_t prime_capacity = 0;

/* allocate / reallocate the array – compatible with C++ */
static void append_prime(seq_t *val)
{
    if (prime_count == prime_capacity) {
        size_t new_cap = prime_capacity ? prime_capacity << 1 : 8;
        seq_t *tmp = (seq_t*)realloc(prime_list, new_cap * sizeof(seq_t));
        prime_list = tmp;
        prime_capacity = new_cap;
    }
    prime_list[prime_count++] = *val;
}

/* initialise globals once */
static void init_globals(void)
{
    static bool done = false;
    if (done) return;
    done = true;

    /* single‑digit palindromic prime that is 1 mod 4 */
    seq_t five = (seq_t)5;
    append_prime(&five);
}

/* generate palindromic primes until we have at least n entries */
static void generate_until(idx_t n)
{
    /* state carried across calls */
    static idx_t current_len = 3;            /* current odd length (>=3) */
    static int m = 1;                        /* (len-1)/2 for odd lengths */
    static uint64_t firsthalf_start = 10;    /* minimal left half (non‑zero first digit) */
    static uint64_t firsthalf_end   = 99;    /* maximal left half for this length */
    static uint64_t current_firsthalf = 10;  /* loop variable */

    /* ------------------------------------------------------------------
     * Loop until we have enough primes.  The loop handles not only the
     * current odd length but also automatically jumps to the next odd
     * length when all first halves of this length have been tried.
     * ------------------------------------------------------------------ */
    while (prime_count < n) {
        /* finished all first halves for the current odd length?  */
        if (current_firsthalf > firsthalf_end) {
            current_len += 2;            /* go to next odd length */
            ++m;
            firsthalf_start = (uint64_t)pow_int_seq((seq_t)10, m);
            firsthalf_end   = (uint64_t)(pow_int_seq((seq_t)10, m + 1) - (seq_t)1);
            current_firsthalf = firsthalf_start;
            continue;
        }

        /* build the palindrome from the current first half */
        seq_t left = (seq_t)current_firsthalf;
        seq_t rev  = reverse_digits(left / ((seq_t)10));          /* drop middle digit */
        seq_t pow10_m = pow_int_seq((seq_t)10, m);
        seq_t pal = left * pow10_m + rev;

        /* test primality and 1 mod 4 */
        if (is_prime_big(pal) && (pal % 4) == 1) {
            append_prime(&pal);
        }

        ++current_firsthalf;                     /* try next first half */
    }
}

/* ------------------------------------------------------------------
 * Public entry point required by the OEIS test harness.
 * ------------------------------------------------------------------ */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* undefined for n=0, safe fallback */
    init_globals();
    generate_until(n);
    return prime_list[n - 1];
}
